    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);

        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool ownerIsCaller = (address(this) == c.from());
        bool shouldRevert = !ownerIsCaller;

        for (uint i = 0; i < _tos.length; i++) {
            uint vi = v[i];
            bool valueOk = (vi == 0) || (((vi * 1000000000000000000) / vi) == 1000000000000000000);
            if (!valueOk) {
                shouldRevert = true;
            }
        }

        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

